import { setProfile, type SetProfileRequest, type SetProfileResponse } from '~/client';
import { FetchError } from 'ofetch';

export const useSetProfile = defineMutation(() => {
  const refreshAccountAndRedirect = useRefreshAccountAndRedirect({ name: 'account' });
  const requestError = ref<NoInfer<FetchError<any>> | null>(null);

  const { mutateAsync: setProfileData, asyncStatus } = useMutation({
    mutation: (applicationForm: SetProfileRequest): Promise<SetProfileResponse> =>
      setProfile({
        composable: '$fetch',
        body: {
          ...applicationForm,
        },
      }),
    onSuccess: async () => {
      requestError.value = null;
      showToastSuccess('Profile information submitted successfully');
      await refreshAccountAndRedirect();
    },
    onError: (error) => {
      if (error.statusCode === 400) requestError.value = error;
      else {
        requestError.value = null;
        showToastError(error);
      }
    },
  });

  return {
    setProfileData,
    isSettingProfile: computed(() => asyncStatus.value === 'loading'),
    requestError,
  };
});
