<template>
  <form
    class="self-center flex flex-col gap-4 flex-auto w-full justify-center max-w-[700px] max-lg:px-0"
    @submit="onSubmit"
  >
    <FormItemWrapper
      v-for="field in qaFields"
      :key="field.id"
      :label="field.question"
      :name="field.id"
      :validate-on-model-update="false"
      :validate-on-blur="false"
      :validate-on-change="false"
    >
      <template #default="{ slots }">
        <Input id="field.id" type="text" v-bind="slots.componentField" />
      </template>
    </FormItemWrapper>
    <Button type="submit" class="h-10 self-end">Next</Button>
  </form>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import type { ProfileQAField } from '~/types/account/profileQAFields';

interface Props {
  qaFields: ProfileQAField[];
}
const props = defineProps<Props>();

interface Emits {
  (e: 'update-is-questions', value: boolean): void;

  (e: 'on-update-qa-fields', event: ProfileQAField[]): void;

  (e: 'on-update-generated-bio', string: string): void;
}
const emits = defineEmits<Emits>();

//TODO: mb its possible to make typed schema dynamically
const formSchema = toTypedSchema(
  z.object({
    interesting_fact: z
      .string({ message: 'Interesting fact is required' })
      .trim()
      .min(40, { message: 'Answer must be at least 40 characters' })
      .max(5000, { message: 'Answer must not exceed 5000 characters' }),
    work_reason: z
      .string({ message: 'Work reason is required' })
      .trim()
      .min(40, { message: 'Answer must be at least 40 characters' })
      .max(5000, { message: 'Answer must not exceed 5000 characters' }),
    conservatism_belief: z
      .string({ message: 'Conservatism belief is required' })
      .trim()
      .min(40, { message: 'Answer must be at least 40 characters' })
      .max(5000, { message: 'Answer must not exceed 5000 characters' }),
  })
);

const { handleSubmit, setFieldValue } = useForm({
  validationSchema: formSchema,
});

const onSubmit = handleSubmit(async (values) => {
  const updatedQAFields = props.qaFields.map((field) => ({
    ...field,
    answer: values[field.id],
  }));
  emits('on-update-qa-fields', updatedQAFields);
  emits('update-is-questions', true);
});

onBeforeMount(() => {
  for (const field of props.qaFields) {
    setFieldValue(field.id, field.answer);
  }
});
</script>

<style scoped lang="scss"></style>
