<template>
  <CanvasserFormWrapper title="Canvasser Profile">
    <form
      id="canvasser-profile-create-form"
      class="self-center flex flex-col gap-6 flex-auto w-full justify-center max-w-[700px] max-lg:px-0"
      @submit="onSubmit"
    >
      <div class="flex flex-col gap-4">
        <Alert v-if="error" variant="destructive">
          <AlertTitle class="flex gap-2 items-center"><TriangleAlert />Failed to submit profile information</AlertTitle>
          <AlertDescription>
            <p class="whitespace-pre-wrap">
              {{ error?.data.detail || 'An unexpected error occurred while submitting your profile information.' }}
            </p>
          </AlertDescription>
        </Alert>
        <p class="font-medium">Photo</p>
        <p class="text-sm">Please upload photo of yourself in format below (.png, .jpg, .jpeg).</p>
        <FormItemWrapper name="profile_picture_url">
          <template #default="{ slots }">
            <ImageCropUpload
              circle
              helper-text="Click to upload a photo (PNG or JPG)"
              :disabled="isSettingProfile"
              v-bind="slots.componentField"
              @update:uploading="(value) => (isPhotoUploading = value)"
            />
          </template>
        </FormItemWrapper>
      </div>
      <div class="flex flex-col gap-4">
        <p class="font-medium">Bio</p>
        <AccountCanvasserBioForm
          v-if="!isQuestions"
          :qa-fields="qaFields"
          @on-update-qa-fields="onUpdateQAFields"
          @update-is-questions="onUpdateIsQuestions"
          @on-update-generated-bio="onUpdateGeneratedBio"
        />
        <template v-else>
          <AccountCanvasserBioGenerated
            :qa-fields="qaFields"
            @update-is-questions="onUpdateIsQuestions"
            @on-update-generated-bio="onUpdateGeneratedBio"
          />
          <Button
            type="submit"
            form="canvasser-profile-create-form"
            :loading="isSettingProfile"
            :disabled="isPhotoUploading || isGeneratingBio"
          >
            Submit Information
          </Button>
        </template>
      </div>
    </form>
  </CanvasserFormWrapper>
</template>

<script lang="ts" setup>
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { canvasserProfileQuestions } from '~/constants/account';
import { useSetProfile } from '~/mutations/account';
import type { ProfileQAField } from '~/types/account/profileQAFields';
import { TriangleAlert } from 'lucide-vue-next';
import { useGenerateBio } from '~/mutations/account';

// The account/create.vue layout passes :account-info, which this step does not need
// (it starts a blank profile form). Don't let it fall through onto the form wrapper.
defineOptions({ inheritAttrs: false });

useHead({ title: 'Profile' });

const isQuestions = ref<boolean>(false);
const isPhotoUploading = ref<boolean>(false);
const qaFields = ref<ProfileQAField[]>(canvasserProfileQuestions);

const { isGeneratingBio } = useGenerateBio();

const formSchema = toTypedSchema(
  z.object({
    generated_bio: z
      .string({ message: 'Generated bio is required' })
      .trim()
      .min(200, { message: 'Bio must be at least 200 characters' })
      .max(1000, { message: 'Bio must not exceed 1000 characters' }),
    profile_picture_url: z
      .string({ message: 'Profile image is required' })
      .min(1, { message: 'Profile image is required' }),
  })
);

const { handleSubmit, setFieldValue } = useForm({
  validationSchema: formSchema,
  initialValues: { profile_picture_url: '' },
});

const { setProfileData, isSettingProfile, requestError: error } = useSetProfile();

const onSubmit = handleSubmit(async (values) => {
  await setProfileData({ bio: values.generated_bio, profile_picture_url: values.profile_picture_url }).catch((err) => {
    console.error('Error submitting form:', err);
  });
});

function onUpdateIsQuestions(value: boolean) {
  isQuestions.value = value;
}
function onUpdateQAFields(values: ProfileQAField[]) {
  qaFields.value = values;
}
function onUpdateGeneratedBio(value: string) {
  setFieldValue('generated_bio', value);
}

onUnmounted(() => {
  qaFields.value = canvasserProfileQuestions;
  error.value = null;
});
</script>
