<template>
  <Alert :variant="alertVariant">
    <template v-if="isGeneratingBio">
      <Spinner class="w-5 h-5 fill-foreground" />
      <AlertTitle class="w-fit">Generating Bio</AlertTitle>
      <AlertDescription>Based on your answers to the questions with AI ✨</AlertDescription>
    </template>
    <template v-else-if="error">
      <XIcon />
      <AlertTitle class="w-fit">Failed to generate Bio</AlertTitle>
      <AlertDescription class="w-fit">{{ error?.data.detail }}</AlertDescription>
    </template>
    <template v-else-if="isBioGenerationSuccess">
      <CheckIcon />
      <AlertTitle class="w-fit">Bio generated successfully</AlertTitle>
      <AlertDescription class="w-fit">You can edit it below</AlertDescription>
    </template>
  </Alert>
  <div class="flex flex-wrap gap-2 sm:gap-4">
    <Button
      type="button"
      class="w-full sm:w-auto"
      variant="outline"
      :prepend-icon="ChevronLeftIcon"
      :disabled="isGeneratingBio || isSettingProfile"
      @click="onBackToQuestions"
      >Back to Questions</Button
    >
    <Button
      type="button"
      class="w-full sm:w-auto"
      variant="outline"
      :disabled="isSettingProfile"
      :loading="isGeneratingBio"
      :prepend-icon="SparklesIcon"
      @click="onRegenerateBio"
      >{{ isBioGenerationSuccess ? 'Regenerate Bio' : 'Try Generate Again' }}</Button
    >
  </div>
  <FormItemWrapper
    name="generated_bio"
    :validate-on-model-update="false"
    :validate-on-blur="false"
    :validate-on-change="false"
  >
    <template #default="{ slots }">
      <Textarea
        id="generated_bio"
        rows="10"
        maxlength="1000"
        :disabled="isGeneratingBio || isSettingProfile"
        v-bind="slots.componentField"
      />
    </template>
  </FormItemWrapper>
</template>

<script setup lang="ts">
import { Spinner } from '~/assets/icons';
import { useGenerateBio, useSetProfile } from '~/mutations/account';
import { XIcon, CheckIcon, ChevronLeftIcon, SparklesIcon } from 'lucide-vue-next';
import type { ProfileQAField } from '~/types/account/profileQAFields';

interface Props {
  qaFields: ProfileQAField[];
}
const props = defineProps<Props>();

interface Emits {
  (e: 'update-is-questions', value: boolean): void;

  (e: 'on-update-generated-bio', string: string): void;
}
const emits = defineEmits<Emits>();

const isBioGenerationSuccess = ref<boolean>(true);

const { generateBio, isGeneratingBio, error, status, reset: resetBioError } = useGenerateBio();

// Clear any stale shared bio-generation error from a previous flow on mount.
onMounted(() => resetBioError());
const { isSettingProfile } = useSetProfile();

async function onRegenerateBio() {
  await requestBioGeneration();
}

function onBackToQuestions() {
  emits('update-is-questions', false);
  isBioGenerationSuccess.value = true;
}

onMounted(async () => {
  await requestBioGeneration();
});

async function requestBioGeneration() {
  const mappedQAFields = props.qaFields.map((field) => {
    const { answer, question } = field;
    return {
      question,
      answer: answer ? answer : '',
    };
  });
  try {
    const response = await generateBio({ answers: [...mappedQAFields] });
    emits('on-update-generated-bio', response.bio);
    isBioGenerationSuccess.value = true;
  } catch (error) {
    console.error('Error generating bio:', error);
    isBioGenerationSuccess.value = false;
  }
}

const alertVariant = computed(() => {
  if (isGeneratingBio.value) return 'default';
  if (error.value) return 'destructive';
  if (status.value === 'success') return 'success';
});
</script>

<style scoped lang="scss"></style>
